{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C06"],
      "claim": "In humans, lycopene—a large, highly lipophilic isoprenoid with no ionizable groups—showed only 0.17% systemic availability after oral ingestion, demonstrating that this physicochemical class has intrinsically very poor oral absorption.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C14"],
      "claim": "One stable-isotope lycopene study reported 23.2% bioavailability for all-trans lycopene, an outlier suggesting that absorption can be higher under specific analytical or formulation conditions, but it does not reflect the consistently low F seen in other direct lycopene measurements.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C13"],
      "claim": "A small, ionizable drug with 34% oral bioavailability in humans shows that moderate F is achievable in drug-like chemical space, but its low molecular weight and polar ionizable groups are not representative of the query's extreme lipophilicity and lack of ionizable groups.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is a large, extremely lipophilic polyisoprenoid quinone (CoQ9) with no ionizable groups and very poor predicted solubility. The only structurally relevant experimental evidence, from lycopene—a similarly large lipophilic isoprenoid—shows consistently very low oral bioavailability (mostly <3%), with one outlier at 23.2%. High-transfer small-molecule records with moderate F are not structurally applicable. Therefore, F <20% is better supported.",
  "evidence_gaps": [
    "No direct oral bioavailability data for CoQ9 or CoQ10 in the provided evidence.",
    "Lycopene transferability is low, and its linear polyene structure differs from the quinone core.",
    "Formulation effects on absorption are unknown for the query."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

